// onClipEvent(load)
void clip_4403_27_0(Activation& scope) {
    if (_root["lvl4GreenSwitch"] == true) {
        scope["activated"] = true;
    }
    scope["Switchfunction"] = scope.function([](Activation& scope) -> Value {
        _root["lvl4GreenSwitch"] = true;
        _root["Mariosound"] = new_(Sound, scope.self);
        _root["Mariosound"]["attachSound"]("Boo");
        _root["Mariosound"]["start"](0, 1);
        _root["Mariosound"]["setVolume"](_root["MarioVolume"]);
        scope["count"] = 0;
        scope["onEnterFrame"] = scope.function([](Activation& scope) -> Value {
            scope["count"]++;
            if (scope["count"] > 5 && _root["Course"]["Char"]["air"] == false) {
                scope["count"] = 0;
                //
                _root["PlayMessage"]("Ghost: GAAHH! You've activated 1 of the 2 Ghostly Switches!  Now you might be able to steal our locked up Star!");
                scope["onEnterFrame"] = scope.function([](Activation& scope) -> Value {
                    //
                    _root["playpause"] = true;
                    //
                    scope["count"]++;
                    if ((_root["KeySPACE"]() || _root["KeyZ"]() || _root["KeyX"]()) && scope["count"] > 5) {
                        _root["StopMessage"]();
                        //
                        scope["count"] = 0;
                        scope["onEnterFrame"] = scope.function([](Activation& scope) -> Value {
                            scope["count"]++;
                            if (scope["count"] > 5) {
                                _root["playpause"] = false;
                                _root["Course"]["Char"]["attack"] = false;
                                scope["onEnterFrame"] = Value::null();
                                gotoAndStop("end");
                            }
                            return undefined;
                        });
                    }
                    return undefined;
                });
            }
            return undefined;
        });
        return undefined;
    });
}

