void frame_4652_0(Activation& scope) {
    stop();
    _root["AreaTextClipF"]("Lethal Lava Land" + scope["newline"] + "<i>(Course #5)</i>", 35);
    _root["warpframe"] = false;
    scope["onEnterFrame"] = scope.function([](Activation& scope) -> Value {
        if (scope.self["warp1"]["hitTest"](_root["Course"]["Char"]["charClip"]["feet"])) {
            _root["Course"]["Char"]["attack"] = true;
            _root["Course"]["Char"]["xspeed"] = 0;
            _root["Course"]["Char"]["yspeed"] = 0;
            _root["Course"]["Char"]["attackFrame"] = "none";
            scope["warp"] = true;
            scope["warpnum"] = 1;
        }
        if (scope.self["warp2"]["hitTest"](_root["Course"]["Char"]["charClip"]["feet"])) {
            _root["Course"]["Char"]["attack"] = true;
            _root["Course"]["Char"]["xspeed"] = 0;
            _root["Course"]["Char"]["yspeed"] = 0;
            _root["Course"]["Char"]["attackFrame"] = "none";
            scope["warp"] = true;
            scope["warpnum"] = 2;
        }
        if (scope.self["warp3"]["hitTest"](_root["Course"]["Char"]["charClip"]["feet"])) {
            _root["Course"]["Char"]["attack"] = true;
            _root["Course"]["Char"]["xspeed"] = 0;
            _root["Course"]["Char"]["yspeed"] = 0;
            _root["Course"]["Char"]["attackFrame"] = "none";
            scope["warp"] = true;
            scope["warpnum"] = 3;
        }
        if (scope["warp"] == true && _root["warpframe"] == false) {
            if (scope["warpnum"] == 1) {
                _root["attachMovie"]("righttransition", "lefttransition" + _root["getNextHighestDepth"](), _root["getNextHighestDepth"](), obj({{"_x", _root["screensizeX"] / 2}, {"_y", _root["screensizeY"] / 2}}));
            } else if (scope["warpnum"] == 2) {
                _root["attachMovie"]("righttransition", "righttransition" + _root["getNextHighestDepth"](), _root["getNextHighestDepth"](), obj({{"_x", _root["screensizeX"] / 2}, {"_y", _root["screensizeY"] / 2}}));
            } else {
                _root["attachMovie"]("lefttransition", "lefttransition" + _root["getNextHighestDepth"](), _root["getNextHighestDepth"](), obj({{"_x", _root["screensizeX"] / 2}, {"_y", _root["screensizeY"] / 2}}));
            }
            scope["warp"] = false;
        }
        if (_root["warpframe"] == true) {
            if (scope["warpnum"] == 1) {
                _root["changecourse"]("righttransition2", "5-2", 0, _root["Course"]["Char"]["_y"] - _root["Course"]["BackGFX"]["_y"] - 160, 0, _root["Course"]["Char"]["_y"] - _root["Course"]["BackGFX"]["_y"] - 160);
            } else if (scope["warpnum"] == 2) {
                _root["changecourse"]("uptransition2", "5-9", 0, 0, 0, 0, true);
            } else {
                _root["changecourse"]("lefttransition2", "5-3", 0, _root["Course"]["Char"]["_y"] - _root["Course"]["BackGFX"]["_y"] - 160, 0, _root["Course"]["Char"]["_y"] - _root["Course"]["BackGFX"]["_y"] - 160);
            }
            //_root.warpframe = false;
        }
        return undefined;
    });
    gotoAndStop(_root["Starnum"] + 2);
    stop();
}

