void frame_4723_0(Activation& scope) {
    stop();
    _root["warpframe"] = false;
    scope["onEnterFrame"] = scope.function([](Activation& scope) -> Value {
        if (scope.self["warp1"]["hitTest"](_root["Course"]["Char"]["charClip"]["feet"])) {
            _root["Course"]["Char"]["attack"] = true;
            _root["Course"]["Char"]["xspeed"] = 0;
            _root["Course"]["Char"]["yspeed"] = 0;
            _root["Course"]["Char"]["attackFrame"] = "none";
            scope["warp"] = true;
            scope["warpnum"] = 1;
        }
        if (scope.self["warp2"]["hitTest"](_root["Course"]["Char"]["charClip"]["feet"])) {
            _root["Course"]["Char"]["attack"] = true;
            _root["Course"]["Char"]["xspeed"] = 0;
            _root["Course"]["Char"]["yspeed"] = 0;
            _root["Course"]["Char"]["attackFrame"] = "none";
            scope["warp"] = true;
            scope["warpnum"] = 2;
        }
        if (scope.self["warp3"]["hitTest"](_root["Course"]["Char"]["charClip"]["feet"])) {
            _root["Course"]["Char"]["attack"] = true;
            _root["Course"]["Char"]["xspeed"] = 0;
            _root["Course"]["Char"]["yspeed"] = 0;
            _root["Course"]["Char"]["attackFrame"] = "none";
            scope["warp"] = true;
            scope["warpnum"] = 3;
        }
        if (scope["warp"] == true && _root["warpframe"] == false) {
            if (scope["warpnum"] == 1) {
                _root["attachMovie"]("lefttransition", "lefttransition" + _root["getNextHighestDepth"](), _root["getNextHighestDepth"](), obj({{"_x", _root["screensizeX"] / 2}, {"_y", _root["screensizeY"] / 2}}));
            }
            if (scope["warpnum"] == 2) {
                _root["attachMovie"]("righttransition", "righttransition" + _root["getNextHighestDepth"](), _root["getNextHighestDepth"](), obj({{"_x", _root["screensizeX"] / 2}, {"_y", _root["screensizeY"] / 2}}));
            }
            if (scope["warpnum"] == 3) {
                _root["attachMovie"]("lefttransition", "lefttransition" + _root["getNextHighestDepth"](), _root["getNextHighestDepth"](), obj({{"_x", _root["screensizeX"] / 2}, {"_y", _root["screensizeY"] / 2}}));
            }
            scope["warp"] = false;
        }
        if (_root["warpframe"] == true) {
            if (scope["warpnum"] == 1) {
                _root["changecourse"]("lefttransition2", "5-4", 1765, _root["Course"]["Char"]["_y"] - _root["Course"]["BackGFX"]["_y"], 1765, _root["Course"]["Char"]["_y"] - _root["Course"]["BackGFX"]["_y"]);
            }
            if (scope["warpnum"] == 2) {
                _root["changecourse"]("righttransition2", "5-1", -280, _root["Course"]["Char"]["_y"] - _root["Course"]["BackGFX"]["_y"] + 160, -280, _root["Course"]["Char"]["_y"] - _root["Course"]["BackGFX"]["_y"] + 160);
            }
            if (scope["warpnum"] == 3) {
                _root["changecourse"]("lefttransition2", "5-3", 0, 0, 0, 0);
            }
            //_root.warpframe = false;
        }
        return undefined;
    });
}

